llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Zilascorb(2H), a benzylidene-protected ascorbic acid derivative, had absolute oral bioavailability of 34 ± 13% in patients, directly demonstrating that the ascorbic acid scaffold can achieve F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Oral mannitol, a very polar polyol, showed mean absolute bioavailability of 63% in healthy adult men, supporting that small polar molecules can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "D-xylose, a polar pentose, had oral bioavailability of 98% versus i.v. in healthy volunteers, indicating efficient absorption of polar sugars.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Sorbitol, a polar hexitol, showed bioavailability of 0.38 ± 0.11 in shunted patients, another example of a polar sugar alcohol exceeding 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Fructose, a polar monosaccharide, had only 14.5 ± 0.8% systemic availability due to first-pass splanchnic extraction, providing a counterexample below the threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest analogue, zilascorb(2H), an ascorbic acid derivative, has absolute oral bioavailability of 32-34%, above the 20% threshold. Related polar sugars/polyols (mannitol, sorbitol, xylose) also show F ≥20-98%, indicating that small polar molecules can be sufficiently absorbed. The low physicochemical prior is outweighed by these experimental data and by the known active transport of ascorbic acid. Fructose's lower F is due to first-pass splanchnic extraction, not poor absorption.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for ascorbic acid itself is present in the evidence set.",
    "Zilascorb(2H) is a protected/lipophilic prodrug; its absorption may not fully reflect the permeability of the free acid.",
    "Dose-dependent active transport (SVCT1/2) and saturation are not captured in the physicochemical prior or the analogue records.",
    "The sugar/polyol analogues are uncharged, whereas the query is ionized at physiological pH."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

